mapper.delete:
DELETE FROM BOK_DETAIL_ID
WHERE BOOKSET_ID = #{booksetId}
  and TRADE_ID = #{tradeId}

mapper.select:
SELECT
,T2.CASH_TYPE_2 FROM FIN_CASH_PLAN T1, FIN_CASH_INFO T2 WHERE T2.CASH_ID = T1.CASH_ID
AND T2.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND T2.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
AND T2.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
ORDER BY T1.VDATE ASC
